11	  const [tasks, setTasks] = useState<Task[]>(initialTasks);
12	  const [selectedId, setSelectedId] = useState<number>(initialTasks[0].id);
13	  const [editingId, setEditingId] = useState<number | null>(null);
14	
15	  const selectedTask = tasks.find((task) => task.id === selectedId) ?? tasks[0];
16	  const editingTask = tasks.find((task) => task.id === editingId) ?? null;
17	
18	  const updateTask = (updated: Task) => {
19	    setTasks((current) => current.map((task) => (task.id === updated.id ? updated : task)));
20	    setEditingId(null);
21	  };
22	
23	  const addTask = (title: string) => {
24	    const task: Task = {
25	      id: Math.max(...tasks.map((item) => item.id)) + 1,
26	      title,
27	      owner: 'You',
28	      status: 'Todo',
29	      priority: 'Medium',
30	    };
31	    setTasks((current) => [...current, task]);
32	    setSelectedId(task.id);
33	  };
34	
35	  return (
36	    <div className="app-shell">
37	      <ResponsiveNav />
38	      <main>
39	        <header className="hero">
40	          <div>
41	            <p className="eyebrow">Product operations</p>
42	            <h1>RegressionBoard</h1>
43	            <p>Keep routine interface changes from surprising existing users.</p>
44	          </div>
45	          <span className="task-count" aria-label={`${tasks.length} tasks`}>{tasks.length} tasks</span>
46	        </header>
47	
48	        <div className="dashboard-grid">
49	          <section className="card task-card" aria-labelledby="task-list-title">
50	            <div className="section-heading">
51	              <div>
52	                <p className="eyebrow">Workspace</p>
53	                <h2 id="task-list-title">Tasks</h2>
54	              </div>
55	            </div>
56	            <TaskList
57	              tasks={tasks}
58	              selectedId={selectedId}
59	              onSelect={setSelectedId}
60	              onEdit={setEditingId}
61	            />
62	          </section>
63	
64	          <aside className="stack">
65	            <section className="card detail-card" aria-labelledby="selected-title">
66	              <p className="eyebrow">Selected task</p>
67	              <h2 id="selected-title">{selectedTask.title}</h2>
68	              <dl>
69	                <div><dt>Owner</dt><dd>{selectedTask.owner}</dd></div>
70	                <div><dt>Status</dt><dd>{selectedTask.status}</dd></div>
71	                <div><dt>Priority</dt><dd>{selectedTask.priority}</dd></div>
72	              </dl>
